def media_path(folder: Path, raw: str) -> Path | None:
    """An existing video, audio or image file inside the allowed folders, else None."""
    path = Path(os.path.expanduser(raw.strip()))
    if not path.is_absolute():
        path = folder / path
    try:
        path = path.resolve(strict=True)
    except (OSError, RuntimeError):
        return None
    if path.suffix.lower().lstrip(".") not in MEDIA or not path.is_file():
        return None
    return path if any(path.is_relative_to(r) for r in media_roots(folder)) else None

async def _vs(method: str, path: str, **kw) -> httpx.Response:
    try:
        async with httpx.AsyncClient(timeout=300) as c:
            r = await c.request(method, VS_URL + path, headers=_vs_headers(), **kw)
    except httpx.HTTPError as e:
        raise HTTPException(503, f"VoiceStudio is not reachable at {VS_URL} ({type(e).__name__})")
    if r.status_code >= 400:
        try:
            msg = r.json().get("error", {}).get("message") or r.text
        except ValueError:
            msg = r.text
        raise HTTPException(r.status_code, f"VoiceStudio: {msg[:300]}")

